#! /usr/local/bin/pike

// The Very Simple World Wide Web Browser

int main(int argc, array(string) argv)
{
  write("Welcome to the Very Simple WWW Browser!\n");
  string url;
  if(argc == 2)
    url = argv[1];
  else
  {
    write("Type the address of the web page:\n");
    url = Stdio.stdin->gets();
  }
  write("URL: " + url + "\n");
  return 0;
} // main
